+/**
+ * Calculate revenue totals for a standard sale.
+ * @param {Object} input
+ * @param {number} input.unitPrice - Non-negative currency amount.
+ * @param {number} input.quantity - Non-negative integer quantity.
+ * @param {number} [input.discount=0] - Discount from subtotal, non-negative.
+ * @param {number} [input.taxRate=0] - Tax rate as decimal fraction, e.g. 0.2.
+ * @returns {{subtotal:number, discount:number, taxable:number, tax:number, total:number}}
+ */
+export function calculateRevenue({ unitPrice, quantity, discount = 0, taxRate = 0 }) {
+  if (!Number.isFinite(unitPrice) || unitPrice < 0) {
+    throw new TypeError('unitPrice must be a non-negative number');
+  }
+
+  if (!Number.isInteger(quantity) || quantity < 0) {
+    throw new TypeError('quantity must be a non-negative integer');
+  }
+
+  if (!Number.isFinite(discount) || discount < 0) {
+    throw new TypeError('discount must be a non-negative number');
+  }
+
+  if (!Number.isFinite(taxRate) || taxRate < 0) {
+    throw new TypeError('taxRate must be a non-negative number');
+  }
+
+  const roundCurrency = (value) => Math.round((value + Number.EPSILON) * 100) / 100;
+
+  const subtotal = roundCurrency(unitPrice * quantity);
+  const appliedDiscount = roundCurrency(Math.min(discount, subtotal));
+  const taxable = roundCurrency(subtotal - appliedDiscount);
+  const tax = roundCurrency(taxable * taxRate);
+  const total = roundCurrency(taxable + tax);
+
+  return { subtotal, discount: appliedDiscount, taxable, tax, total };
+}
