+export type RevenueRequest = {
+  orderId: string;
+  transactionRef: string;
+  customerId: string;
+  currency: string;
+  amount: number;
+  status: 'PENDING' | 'COMPLETED' | 'CANCELLED';
+};
+
+export type RevenueRecord = {
+  orderId: string;
+  transactionRef: string;
+  customerId: string;
+  currency: string;
+  amount: number;
+  recognizedAt: string;
+};
+
+export interface RevenueRepository {
+  findByTransactionRef(transactionRef: string): Promise<RevenueRecord | null>;
+  save(record: RevenueRecord): Promise<RevenueRecord>;
+}
+
+const SUPPORTED_CURRENCIES = new Set(['USD', 'EUR', 'GBP']);
+
+export function validateRevenueRequest(input: RevenueRequest): void {
+  if (!input.orderId || !input.orderId.trim()) throw new Error('orderId is required');
+  if (!input.transactionRef || !input.transactionRef.trim()) throw new Error('transactionRef is required');
+  if (!input.customerId || !input.customerId.trim()) throw new Error('customerId is required');
+  if (!Number.isFinite(input.amount) || input.amount <= 0) throw new Error('amount must be greater than 0');
+  if (!SUPPORTED_CURRENCIES.has(input.currency)) throw new Error('unsupported currency');
+}
+
+export async function recognizeRevenue(
+  input: RevenueRequest,
+  repo: RevenueRepository,
+  now: () => string = () => new Date().toISOString()
+): Promise<RevenueRecord | null> {
+  validateRevenueRequest(input);
+
+  if (input.status !== 'COMPLETED') {
+    return null;
+  }
+
+  const existing = await repo.findByTransactionRef(input.transactionRef);
+  if (existing) {
+    return existing;
+  }
+
+  const record: RevenueRecord = {
+    orderId: input.orderId.trim(),
+    transactionRef: input.transactionRef.trim(),
+    customerId: input.customerId.trim(),
+    currency: input.currency,
+    amount: input.amount,
+    recognizedAt: now(),
+  };
+
+  return repo.save(record);
+}
+
