export type RevenueType = 'STANDARD' | 'DISCOUNT' | 'REFUND';

export interface Order {
  amountCents: number;
  type: RevenueType;
}

/**
 * Returns recognized revenue in cents for an order.
 *
 * Domain note:
 * - STANDARD and DISCOUNT orders recognize their provided non-negative amount.
 * - REFUND orders recognize 0 here because refund processing is tracked separately
 *   from recognized revenue in this projection, rather than as negative revenue.
 */
export function calculateRecognizedRevenue(order: Order): number {
  if (!Number.isFinite(order.amountCents)) {
    throw new Error('amountCents must be a finite number');
  }
  if (!Number.isInteger(order.amountCents)) {
    throw new Error('amountCents must be an integer');
  }
  if (order.amountCents < 0) {
    throw new Error('amountCents must be non-negative');
  }

  switch (order.type) {
    case 'STANDARD':
      return order.amountCents;
    case 'DISCOUNT':
      return order.amountCents;
    case 'REFUND':
      return 0;
    default: {
      const exhaustiveCheck: never = order.type;
      throw new Error(`Unsupported revenue type: ${exhaustiveCheck}`);
    }
  }
}
```

